     1	/**
     2	 * AppLogger: the one logger this service uses.
     3	 *
     4	 * Two guarantees, both covered by AppLogger.test.ts:
     5	 * - every line carries the request id it belongs to (`withRequestId`), and
     6	 * - values that look like secrets are redacted before they are written: by key or by shape, at any depth of
     7	 *   the fields, and secret-shaped tokens inside the message text.
     8	 */
     9	export type LogLevel = "info" | "warn" | "error";
    10	
    11	export interface LogLine {
    12	  readonly level: LogLevel;
    13	  readonly requestId: string;
    14	  readonly message: string;
    15	  readonly fields: Record<string, unknown>;
    16	}
    17	
    18	const SECRET_KEY = /(token|secret|password|authorization|apikey|api_key)/i;
    19	const SECRET_VALUE = /^(sk-[A-Za-z0-9_-]{8,}|Bearer\s+\S+)$/;
    20	const SECRET_IN_TEXT = /(sk-[A-Za-z0-9_-]{8,}|Bearer\s+\S+)/g;
    21	
    22	/**
    23	 * Replaces secret-looking values with "[REDACTED]" at every depth: a key that names a secret, a string value
    24	 * shaped like one, inside nested objects and arrays alike. Other values pass through unchanged.
    25	 */
    26	export function redact(fields: Record<string, unknown>): Record<string, unknown> {
    27	  return redactValue(fields) as Record<string, unknown>;
    28	}
    29	
    30	function redactValue(value: unknown): unknown {
    31	  if (Array.isArray(value)) return value.map(redactValue);
    32	  if (value !== null && typeof value === "object") {
    33	    const out: Record<string, unknown> = {};
    34	    for (const [key, v] of Object.entries(value as Record<string, unknown>)) {
    35	      out[key] = SECRET_KEY.test(key) ? "[REDACTED]" : redactValue(v);
    36	    }
    37	    return out;
    38	  }
    39	  if (typeof value === "string") return SECRET_VALUE.test(value) ? "[REDACTED]" : redactMessage(value);
    40	  return value;
    41	}
    42	
    43	/** Free text: every secret-shaped token inside it is replaced, the rest is kept. Applied to messages and to every string field. */
    44	export function redactMessage(message: string): string {
    45	  return message.replace(SECRET_IN_TEXT, "[REDACTED]");
    46	}
    47	
    48	export type Sink = (line: LogLine) => void;
    49	
    50	export class AppLogger {
    51	  readonly #requestId: string;
    52	  readonly #sink: Sink;
    53	
    54	  private constructor(requestId: string, sink: Sink) {
    55	    this.#requestId = requestId;
    56	    this.#sink = sink;
    57	  }
    58	
    59	  /** A logger bound to one request id. Every line it emits carries that id. */
    60	  static withRequestId(requestId: string, sink: Sink = defaultSink): AppLogger {
    61	    if (requestId.trim() === "") throw new Error("AppLogger requires a non-empty request id");
    62	    return new AppLogger(requestId, sink);
    63	  }
    64	
    65	  get requestId(): string {
    66	    return this.#requestId;
    67	  }
    68	
    69	  info(message: string, fields: Record<string, unknown> = {}): void {
    70	    this.#emit("info", message, fields);
    71	  }
    72	
    73	  warn(message: string, fields: Record<string, unknown> = {}): void {
    74	    this.#emit("warn", message, fields);
    75	  }
    76	
    77	  error(message: string, fields: Record<string, unknown> = {}): void {
    78	    this.#emit("error", message, fields);
    79	  }
    80	
    81	  #emit(level: LogLevel, message: string, fields: Record<string, unknown>): void {
    82	    this.#sink({ level, requestId: this.#requestId, message: redactMessage(message), fields: redact(fields) });
    83	  }
    84	}
    85	
    86	function defaultSink(line: LogLine): void {
    87	  process.stdout.write(`${JSON.stringify(line)}\n`);
    88	}
