     1	/**
     2	 * Request routing: maps a method and path to a handler. Each route receives
     3	 * the request id the handler layer assigned, so anything a route logs goes
     4	 * through AppLogger under that id.
     5	 */
     6	import { AppLogger, type Sink } from "../platform/logging/AppLogger.ts";
     7	
     8	export interface RouteRequest {
     9	  readonly method: "GET" | "POST";
    10	  readonly path: string;
    11	  readonly requestId: string;
    12	  readonly body?: unknown;
    13	}
    14	
    15	export interface RouteResponse {
    16	  readonly status: number;
    17	  readonly body: unknown;
    18	}
    19	
    20	export type RouteHandler = (req: RouteRequest, log: AppLogger) => RouteResponse | Promise<RouteResponse>;
    21	
    22	export class Router {
    23	  readonly #routes = new Map<string, RouteHandler>();
    24	  readonly #sink: Sink | undefined;
    25	
    26	  /** A sink can be supplied so a test can observe what routes log; production uses AppLogger's default. */
    27	  constructor(sink?: Sink) {
    28	    this.#sink = sink;
    29	  }
    30	
    31	  add(method: RouteRequest["method"], path: string, handler: RouteHandler): this {
    32	    this.#routes.set(`${method} ${path}`, handler);
    33	    return this;
    34	  }
    35	
    36	  async dispatch(req: RouteRequest): Promise<RouteResponse> {
    37	    const log = AppLogger.withRequestId(req.requestId, this.#sink);
    38	    const handler = this.#routes.get(`${req.method} ${req.path}`);
    39	    if (!handler) {
    40	      log.warn("no route", { method: req.method, path: req.path });
    41	      return { status: 404, body: { error: "not found" } };
    42	    }
    43	    return handler(req, log);
    44	  }
    45	}
